{
  "title": "The Clockwork Rescue",
  "gate_token": "YjUJF3j35LEy3K-JRjObfw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party gathers at the ruined city's edge.",
      "visual_description": "Dawn light filters through collapsed arches and torn royal banners hanging limp from broken poles. Mara the Cartographer studies a weathered map while the Glass Diver adjusts his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp's first warning echoes from a gatehouse.",
      "visual_description": "At the rusted castle gates, the Oracle Lamp flickers on a stone ledge, its single flame-eye glowing. The Tin Fox stands alert beside it.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara negotiates with the Sleeping Tax Collector.",
      "visual_description": "Inside a crumbling guardroom, the Sleeping Tax Collector dozes on a pile of ledgers, stamped papers stuck to his sleeves. Mara shakes his shoulder impatiently.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver peers into a cursed tower through a window.",
      "visual_description": "A spiraling tower with dark ivy and faintly glowing runes. The Glass Diver presses his helmet against a cracked window, seeing distorted reflections inside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon send the party into hiding.",
      "visual_description": "An armored patrol marches past a collapsed market square. Mara, the Glass Diver, and the Tin Fox crouch behind a fallen statue, shadows sweeping over them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp reveals a hidden passage beneath a royal banner.",
      "visual_description": "A torn banner bearing an old crest hangs over a false wall. The Oracle Lamp's flame casts a beam that outlines a secret door. The Tin Fox sniffs at the seam.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara reads a forbidden map in an abandoned archive.",
      "visual_description": "Dusty shelves and scattered scrolls. Mara unrolls a brittle parchment while the Oracle Lamp hovers overhead, casting warm light on ink symbols.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver swims through a mirror to retrieve a key.",
      "visual_description": "A tall, cracked mirror in a silent hall. The Glass Diver steps through its surface, ripples spreading like water, reaching for a brass key on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Tin Fox scouts ahead and triggers a trap.",
      "visual_description": "A narrow alley with tripwires. The Tin Fox springs forward, disarming one wire but setting off a bell alarm. Its blue eyes flash in alarm.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector wakes just long enough to stamp a pass.",
      "visual_description": "At a checkpoint desk, the Sleeping Tax Collector's hand stamps a parchment without opening his eyes, then he slumps back onto his ledger pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara leads the group through a magic door that shifts corridors.",
      "visual_description": "A stone doorway etched with glowing symbols. Mara touches the frame, and the corridor beyond rotates slowly, revealing a new path. The Glass Diver follows.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp warns of an armored patrol ahead.",
      "visual_description": "At a crossroads, the Oracle Lamp's flame dims and pulses rapidly. Its eye widens as metallic footsteps echo. The party presses against the wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Glass Diver creates a distraction using reflected light.",
      "visual_description": "In a courtyard, the Glass Diver angles his helmet to catch sunlight, sending beams into the eyes of approaching armored figures, buying the party time to slip past.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Tin Fox retrieves a critical map piece from a collapsed tower.",
      "visual_description": "Amid rubble and broken beams, the Tin Fox digs with its metal paws, unearthing a half-burned map fragment. Its key-wind tail ticks steadily.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Mara deciphers the final route to the escape bridge.",
      "visual_description": "In a quiet alcove, Mara spreads the assembled map pieces, tracing a line with her finger. The Oracle Lamp illuminates the path leading to the city's edge.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The party confronts a sealed magic door at the bridge approach.",
      "visual_description": "A massive stone door engraved with interlocking rings blocks the way to the bridge. The Glass Diver places his hand on its surface; the door begins to shimmer.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The Oracle Lamp sacrifices its light to open the door.",
      "visual_description": "The Oracle Lamp flares brightly, its flame leaping into the door's runes, which ignite and dissolve the stone barrier. The lamp's eye fades but remains aflame.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the bridge into dawn.",
      "visual_description": "A long, broken stone bridge spans a misty chasm. The four figures run across as the sun rises behind the ruined city. The Glass Diver's helmet gleams with light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

